//Removes EMPTY plate comments for all functions in the program or over a selection.
//"" is considered the default value for the plate comment.
//@category Update

using ghidra.app.script;
using ghidra.program.model.address;
using ghidra.program.model.listing;

public class DeleteEmptyPlateCommentsScript : GhidraScript {

	private static string EMPTY_PLATE = "";

	/* @Override */
	public void run()
    {
		Listing listing = currentProgram.getListing();
		AddressSetView set = currentProgram.getMemory();
		if (currentSelection != null && !currentSelection.isEmpty()) {
			set = currentSelection;
		}

		int updateCount = 0;
		AddressIterator iter = listing.getCommentAddressIterator(CommentType.PLATE, set, true);
		while (iter.hasNext()) {
			Address addr = iter.next();
			CodeUnit cu = listing.getCodeUnitAt(addr);
			if (cu != null) {
				string[] comment = cu.getCommentAsArray(CommentType.PLATE);
				if (comment.length == 1 && comment[0].equals(EMPTY_PLATE)) {
					cu.setComment(CommentType.PLATE, null);
					++updateCount;
				}
			}
		}
		if (updateCount > 0) {
			string cmt = updateCount > 1 ? "comments" : "comment";
			println("Removed " + updateCount + " emtpy plate " + cmt + ".");
		}
		else {
			println("Did not find any empty plate comments.");
		}
	}
}
